SELECT SUM(amount) AS total_revenue
FROM `pplk8s-lab-001.bet_bare.orders`
WHERE order_date BETWEEN DATE '2026-10-01' AND DATE '2026-10-02';

SELECT COUNT(*) AS total_orders
FROM `pplk8s-lab-001.bet_bare.orders`
WHERE order_date = DATE '2026-10-01';

SELECT COUNT(*) AS shipped_orders_count
FROM `pplk8s-lab-001`.`bet_bare`.`orders` AS orders
WHERE LOWER(orders.status) = 'shipped';

SELECT SUM(amount) AS total_revenue
FROM `pplk8s-lab-001.bet_bare.orders`
WHERE order_date IN (DATE '2026-10-01', DATE '2026-10-02');

SELECT COUNT(DISTINCT order_id) AS shipped_orders_count
FROM `pplk8s-lab-001.bet_bare.orders`
WHERE LOWER(status) = 'shipped';

SELECT COUNT(DISTINCT customer_id) AS total_customers_signed_up
FROM `pplk8s-lab-001`.`bet_bare`.`customers`
WHERE signup_date <= DATE '2026-09-30';

SELECT COUNT(DISTINCT message_id) AS total_messages_sent
FROM `pplk8s-lab-001.bet_bare.outreach_messages`
WHERE sent_date BETWEEN DATE '2026-10-01' AND DATE '2026-10-03';

SELECT COUNT(DISTINCT lead_id) AS total_leads
FROM `pplk8s-lab-001.bet_bare.leads`
WHERE created_date BETWEEN DATE '2026-09-01' AND DATE '2026-09-10';

SELECT COUNT(*) AS total_orders
FROM `pplk8s-lab-001`.`bet_bare`.`orders` AS orders
WHERE orders.order_date = DATE '2026-10-01';
